<?php
declare(strict_types=1);

namespace App\Controllers;

use App\Middleware\AuthMiddleware;
use App\Services\NotificationService;
use App\Services\Support\SupportAttachmentService;
use App\Services\Support\SupportTicketService;
use PDOException;
use Throwable;

final class CommunicationController
{
    public function notifications():void{$user=AuthMiddleware::requireAuthenticated();$page=filter_var($_GET['page']??1,FILTER_VALIDATE_INT);$filter=is_string($_GET['filter']??null)?$_GET['filter']:'all';try{$service=NotificationService::demo();$listing=$service->listForUser((int)$user['id'],$page===false?1:$page,$filter);$this->render('notifications',['listing'=>$listing,'unreadCount'=>$service->getUnreadCount((int)$user['id']),'csrfToken'=>\generate_csrf_token()],'Notifications');}catch(Throwable $e){$this->failed($e,'notifications');}}
    public function support():void{$user=AuthMiddleware::requireAuthenticated();$page=filter_var($_GET['page']??1,FILTER_VALIDATE_INT);$status=is_string($_GET['status']??null)?$_GET['status']:'all';$query=is_string($_GET['q']??null)?$_GET['q']:'';try{$service=SupportTicketService::demo();$this->render('support/index',['listing'=>$service->listUserTickets((int)$user['id'],$page===false?1:$page,$status,$query),'counts'=>$service->getTicketCounts((int)$user['id'])],'Support');}catch(Throwable $e){$this->failed($e,'support');}}
    public function newTicket():void{AuthMiddleware::requireAuthenticated();$this->render('support/new',['categories'=>SupportTicketService::CATEGORIES,'requestToken'=>bin2hex(random_bytes(32)),'csrfToken'=>\generate_csrf_token()],'New Support Ticket');}
    public function ticket(string $reference):void{$user=AuthMiddleware::requireAuthenticated();try{$ticket=SupportTicketService::demo()->getUserTicket((int)$user['id'],$reference);if(!$ticket){http_response_code(404);$this->render('error',['message'=>'Support ticket not found.'],'Ticket Not Found');return;}$ticket['messages']=array_map(static function(array $m):array{$m['message_html']=nl2br(\e($m['message']),false);return $m;},$ticket['messages']);$this->render('support/show',['ticket'=>$ticket,'requestToken'=>bin2hex(random_bytes(32)),'csrfToken'=>\generate_csrf_token()],'Ticket '.$ticket['ticket_number']);}catch(Throwable $e){$this->failed($e,'ticket');}}
    public function markRead(string $reference):void{$this->notificationAction(function(int $id,int $userId):array{$ok=NotificationService::demo()->markRead($userId,$id);return ['message'=>$ok?'Notification marked as read.':'Notification was already read or could not be found.'];},$reference);}
    public function notificationsCount():void{$user=$this->apiUser();if(!$user)return;try{$this->json(200,['success'=>true,'unread'=>NotificationService::demo()->getUnreadCount((int)$user['id'])]);}catch(Throwable $e){$this->actionFailure($e,'notification count');}}
    public function markAllRead():void{$this->notificationAction(function(int $id,int $userId):array{return ['message'=>'Notifications marked as read.','updated'=>NotificationService::demo()->markAllRead($userId)];},'0');}
    private function notificationAction(callable $action,string $reference):void{$user=$this->apiUser();if(!$user)return;if(!$this->csrf()){$this->json(403,['success'=>false,'message'=>'Request verification failed.']);return;}$id=$reference==='0'?0:(preg_match('/^[1-9][0-9]{0,18}$/',$reference)?(int)$reference:0);if($reference!=='0'&&$id<1){$this->json(404,['success'=>false,'message'=>'Notification not found.']);return;}try{$result=$action($id,(int)$user['id']);$this->json(200,['success'=>true,'unread'=>NotificationService::demo()->getUnreadCount((int)$user['id'])]+$result);}catch(Throwable $e){$this->actionFailure($e,'notification');}}
    public function create():void{$user=$this->apiUser();if(!$user)return;if(!$this->csrf()){$this->json(403,['success'=>false,'message'=>'Request verification failed.']);return;}try{$file=is_array($_FILES['attachment']??null)?$_FILES['attachment']:null;$ticket=SupportTicketService::demo()->createTicket((int)$user['id'],is_string($_POST['subject']??null)?$_POST['subject']:'',is_string($_POST['category']??null)?$_POST['category']:'',is_string($_POST['priority']??null)?$_POST['priority']:'normal',is_string($_POST['message']??null)?$_POST['message']:'',is_string($_POST['request_token']??null)?$_POST['request_token']:'',$file);if($this->wantsJson()){$this->json(201,['success'=>true,'ticket'=>$ticket,'url'=>\client_url('support/'.$ticket['ticket_number'])]);return;}\redirect('client/support/'.$ticket['ticket_number']);}catch(Throwable $e){$this->actionFailure($e,'ticket');}}
    public function reply(string $reference):void{$user=$this->apiUser();if(!$user)return;if(!$this->csrf()){$this->json(403,['success'=>false,'message'=>'Request verification failed.']);return;}try{$file=is_array($_FILES['attachment']??null)?$_FILES['attachment']:null;$ticket=SupportTicketService::demo()->addClientReply((int)$user['id'],$reference,is_string($_POST['message']??null)?$_POST['message']:'',is_string($_POST['request_token']??null)?$_POST['request_token']:'',$file);$this->json(200,['success'=>true,'message'=>'Reply sent.','ticket'=>$this->safeTicket($ticket)]);}catch(Throwable $e){$this->actionFailure($e,'reply');}}
    public function close(string $reference):void{$this->statusAction($reference,'close');}
    public function reopen(string $reference):void{$this->statusAction($reference,'reopen');}
    private function statusAction(string $reference,string $action):void{$user=$this->apiUser();if(!$user)return;if(!$this->csrf()){$this->json(403,['success'=>false,'message'=>'Request verification failed.']);return;}try{$s=SupportTicketService::demo();$ok=$action==='close'?$s->close((int)$user['id'],$reference):$s->reopen((int)$user['id'],$reference);$this->json($ok?200:409,['success'=>$ok,'message'=>$ok?($action==='close'?'Ticket closed.':'Ticket reopened.'):'This ticket status cannot be changed.']);}catch(Throwable $e){$this->actionFailure($e,'ticket status');}}
    public function download(string $reference):void{$user=AuthMiddleware::requireAuthenticated();SupportAttachmentService::demo()->streamForOwner($reference,(int)$user['id']);}
    private function render(string $view,array $data,string $title):void{$user=\require_auth();$all=['user'=>$user,'account'=>null,'notifications'=>NotificationService::demo()->recentForUser((int)$user['id']),'notice'=>\flash_get('client_notice'),'error'=>\flash_get('client_error'),'errorMessage'=>null]+$data;$this->setPrivateHeaders();\render('client/layout',['pageTitle'=>$title,'companyName'=>\site_setting('company_name','MultiForex'),'activePage'=>str_starts_with($view,'support')?'support':'notifications','clientView'=>'client/pages/'.$view,'clientData'=>$all,'communicationPage'=>true]);}
    private function setPrivateHeaders():void{header('Cache-Control: private, no-store, no-cache, must-revalidate, max-age=0');header('Pragma: no-cache');header('Expires: 0');}
    private function csrf():bool{return \verify_csrf_token(is_string($_POST['_csrf']??null)?$_POST['_csrf']:null);}
    private function json(int $status,array $payload):void{$this->setPrivateHeaders();http_response_code($status);header('Content-Type: application/json; charset=utf-8');echo json_encode($payload,JSON_UNESCAPED_UNICODE);}
    private function wantsJson():bool{return str_contains(strtolower((string)($_SERVER['HTTP_ACCEPT']??'')),'application/json')||strtolower((string)($_SERVER['HTTP_X_REQUESTED_WITH']??''))==='xmlhttprequest';}
    private function actionFailure(Throwable $e,string $area):void{$status=$e instanceof PDOException?503:422;error_log('Client '.$area.' action failed for user '.(int)(\auth_user_id()??0).': '.$e->getMessage());$message=$e instanceof PDOException?'This request could not be completed. Please try again shortly.':($e instanceof \RuntimeException&&$e->getMessage()!=='csrf'?$e->getMessage():'Request verification failed. Refresh and try again.');$this->json($status,['success'=>false,'message'=>$message]);}
    private function failed(Throwable $e,string $area):void{error_log('Client '.$area.' load failed for user '.(int)(\auth_user_id()??0).': '.$e->getMessage());http_response_code(503);$this->render('error',['message'=>'This information is temporarily unavailable. Please try again.'],'Portal Unavailable');}
    private function safeTicket(array $ticket):array{return ['ticket_number'=>$ticket['ticket_number']??'','status'=>$ticket['status']??'','messages'=>array_map(static function($m){$a=$m['attachment']??null;return ['sender_label'=>$m['sender_label'],'message'=>$m['message'],'created_at'=>$m['created_at'],'attachment'=>$a?['reference'=>$a['attachment_reference'],'filename'=>$a['original_filename'],'file_size'=>$a['file_size']]:null];},$ticket['messages']??[])];}
    private function apiUser():?array{$this->setPrivateHeaders();$id=\auth_user_id();if($id===null||!\auth_check()){$this->json(401,['success'=>false,'message'=>'Your session has expired.','login_url'=>\site_url('login')]);return null;}try{$q=\App\Database::connection()->prepare("SELECT id,first_name FROM users WHERE id=? AND status='active' LIMIT 1");$q->execute([$id]);$u=$q->fetch();if($u)return $u;}catch(Throwable $e){$this->actionFailure($e,'authentication');return null;}\App\Middleware\AuthMiddleware::clearAuthentication();$this->json(401,['success'=>false,'message'=>'Your session has expired.','login_url'=>\site_url('login')]);return null;}
}
